struct Base {
    virtual int value(int x = 10) const { return x; }
    virtual ~Base() = default;
};
struct Derived : Base {
private:
    int value(int x = 99) const override { return x + 1; }
};
int probe() {
    Derived d;
    const Base& b = d;
    return b.value();
}

